<script setup>
import {reactive} from 'vue';
import {Plus,ChevronUp,ChevronDown,Trash2} from 'lucide-vue-next';
import {visibleBlocks,blockLabel} from '../model.js';
const props=defineProps({studio:Object}),s=reactive(props.studio);
function toggle(field,key){const keys=s.current[field]||=[];s.current[field]=keys.includes(key)?keys.filter(k=>k!==key):[...keys,key];}
</script>
<template><section class="pedagogical-editor"><p class="field-help">Duplique l’état, puis modifie les objets sur la diapo. Chaque état garde ses propres textes, positions, styles et notes.</p><div class="pedagogical-row" :class="{active:s.editStep===0}"><button class="step-select" @click="s.selectPedagogicalStep(0)"><span>0</span>État initial</button></div><div v-for="(item,n) in s.baseSlide.pedagogicalSteps" :key="item.id" class="pedagogical-row" :class="{active:s.editStep===n+1}"><button class="step-select" :aria-label="'Éditer '+item.name" @click="s.selectPedagogicalStep(n+1)"><span>{{n+1}}</span>{{item.name}}</button><button class="icon-btn" :disabled="n===0" aria-label="Monter l’étape" @click="s.movePedagogical(n+1,-1)"><ChevronUp :size="13"/></button><button class="icon-btn" :disabled="n===s.baseSlide.pedagogicalSteps.length-1" aria-label="Descendre l’étape" @click="s.movePedagogical(n+1,1)"><ChevronDown :size="13"/></button><button class="icon-btn" :aria-label="'Supprimer l’étape '+(n+1)+' · '+item.name" @click="s.removePedagogical(n+1)"><Trash2 :size="13"/></button></div><button class="btn full" :disabled="s.baseSlide.pedagogicalSteps?.length>=20" @click="s.addPedagogical"><Plus :size="14"/>Créer l’étape suivante</button><label v-if="s.editStep">Titre de l’étape<input v-model="s.baseSlide.pedagogicalSteps[s.editStep-1].name" maxlength="100" aria-label="Titre de l’étape"></label><p class="field-help">Les notes de présentation suivent l’état sélectionné. Les apparitions restent disponibles dans chaque état.</p><div class="step-objects"><div class="step-object-heading"><span>Objets de cet état</span><small>Visible · Focus</small></div><div v-for="key in visibleBlocks(s.current)" :key="key" class="step-object"><span>{{blockLabel(s.current,key)}}</span><input type="checkbox" :aria-label="'Visible : '+blockLabel(s.current,key)" :checked="!s.current.hiddenKeys?.includes(key)" @change="toggle('hiddenKeys',key)"><input type="checkbox" :aria-label="'Mettre en évidence : '+blockLabel(s.current,key)" :checked="s.current.emphasisKeys?.includes(key)" @change="toggle('emphasisKeys',key)"></div></div></section></template>
